//! gxctl's profile configuration file (spec/gxctl-auth.md §2): one JSON
//! file of named profiles, each bundling target + trust + credential,
//! generated by `gxctl auth login`. Reading it obeys the same mode and
//! ownership discipline as the token file it replaces (client.rs), because
//! what it stores is a bearer token.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::io;
use std::os::unix::fs::{DirBuilderExt, MetadataExt, OpenOptionsExt, PermissionsExt};
use std::path::{Path, PathBuf};
use zeroize::Zeroizing;

/// The only `version` this build reads (§2.2).
pub const CONFIG_VERSION: u32 = 1;

fn yes() -> bool {
    true
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields, default)]
pub struct Config {
    pub version: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub current: Option<String>,
    #[serde(default)]
    pub profiles: BTreeMap<String, Profile>,
}

impl Default for Config {
    fn default() -> Self {
        Self { version: CONFIG_VERSION, current: None, profiles: BTreeMap::new() }
    }
}

// Debug prints only what is safe to show: profile names, what they dial,
// how they trust — never a token or the helper line that might carry one
// (gxctl-auth.md §2.1).
impl std::fmt::Debug for Config {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Config { version: ")?;
        std::fmt::Debug::fmt(&self.version, f)?;
        f.write_str(", current: ")?;
        std::fmt::Debug::fmt(&self.current, f)?;
        f.write_str(", profiles: [")?;
        std::fmt::Debug::fmt(&self.profiles.keys().cloned().collect::<Vec<_>>(), f)?;
        f.write_str("] }")
    }
}

impl Config {
    /// Whether this file says anything about where to connect at all; a
    /// file of no profiles keeps gxctl on today's ladder (§3.3).
    pub fn has_any(&self) -> bool {
        !self.profiles.is_empty() || self.current.is_some()
    }

    pub fn list(&self) -> String {
        self.profiles.keys().cloned().collect::<Vec<_>>().join(", ")
    }

    /// gxctl refuses to edit a file it cannot fully parse, so field-name
    /// typos and broken pins fail here and not as silently dropped trust
    /// (§2.2).
    fn validate(&self, path: &Path) -> Result<(), String> {
        if self.version != CONFIG_VERSION {
            return Err(format!("{}: unsupported config version {} (this gxctl writes version {})", path.display(), self.version, CONFIG_VERSION));
        }
        if let Some(cur) = &self.current {
            if self.profiles.get(cur).is_none() {
                return Err(format!("{}: 'current' names '{}', which the file does not define; its profiles are {}", path.display(), cur, self.list()));
            }
        }
        for (name, p) in &self.profiles {
            let e = |what: &str| format!("{}: profile '{}': {what}", path.display(), name);
            if p.url.is_empty() {
                return Err(e("needs at least one url"));
            }
            for u in &p.url {
                let https = u.starts_with("https://");
                let local = u.starts_with("http://") && is_loopback_host(&url_host(u));
                if !https && !local {
                    return Err(e(&format!("url '{u}': https only (plain http is accepted for loopback only, cli.md)")));
                }
            }
            for pin in &p.tls.pins {
                if glidex_tls::Trust::normalize_pin(pin).is_none() {
                    return Err(e(&format!("pin '{pin}' is not a fingerprint in the form gxctl prints, 'sha256/AB:CD:…'")));
                }
            }
            if !p.tls.verify_host && p.tls.pins.is_empty() && !p.tls.insecure {
                // A name-check waiver without a pin is no verification at
                // all dressed as one (§2.2).
                return Err(e("tls.verify_host=false needs a matching tls.pins entry; without a pin it would accept any certificate for any host"));
            }
            if p.tls.insecure {
                // The bypass exists only as a confirmation phrase typed at
                // login (§5.4); hand-editing it in without the phrase is a
                // config error, never a fallback gxctl offers.
                let host = url_host(p.url.first().unwrap_or(&String::new()));
                let phrase = p.tls.i_understand.as_ref().map(|s| s.trim());
                if phrase != Some(host.as_str()) || host.is_empty() {
                    return Err(e(&format!("tls.insecure needs tls.i_understand: \"{}\" typed by the operator ('auth login --insecure' asks for it)", host)));
                }
            }
            if let Some(id) = &p.cluster_id {
                if id.is_empty() || id.chars().any(char::is_control) {
                    return Err(e("cluster_id is not a printable identifier"));
                }
            }
        }
        Ok(())
    }
}

#[derive(Deserialize, Serialize, Default, Clone)]
#[serde(deny_unknown_fields, default)]
pub struct Profile {
    /// One cluster, possibly several of its nodes (§2.2, A7).
    #[serde(default)]
    pub url: Vec<String>,
    /// Written by `auth login` from `/auth/server-info`; mismatch is a
    /// hard error (§4.3). `None` = never verified.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cluster_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cluster_name: Option<String>,
    /// Session default, equal to `--project` (§2.2).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project: Option<String>,
    #[serde(default)]
    pub tls: Tls,
    /// The `gxt_…` secret. `token_command` wins when both are present,
    /// with a warning (§2.2) — a site-wide helper beats a stale copy.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token_command: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub identity: Option<Identity>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub added_at: Option<u64>,
    /// Failover hint (§4.2); losing it costs nothing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_used: Option<LastUsed>,
}

impl std::fmt::Debug for Profile {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Token and token_command print as presence flags only: the
        // secret is not to reach a terminal, nor the command line that
        // may carry one (§2.1).
        f.write_str("Profile { url: ")?;
        std::fmt::Debug::fmt(&self.url, f)?;
        f.write_str(", cluster: ")?;
        std::fmt::Debug::fmt(&self.cluster_name.as_ref().or(self.cluster_id.as_ref()), f)?;
        f.write_str(", trust: ")?;
        std::fmt::Debug::fmt(&self.trust_mode(), f)?;
        f.write_str(", token: ")?;
        std::fmt::Debug::fmt(&self.token.is_some(), f)?;
        f.write_str(", token_command: ")?;
        std::fmt::Debug::fmt(&self.token_command.is_some(), f)?;
        f.write_str(", identity: ")?;
        std::fmt::Debug::fmt(&self.identity, f)?;
        f.write_str(" }")
    }
}

impl Profile {
    /// The trust one-liner of the banner and `auth status` (§6.2).
    pub fn trust_mode(&self) -> String {
        let t = &self.tls;
        if t.insecure {
            return "UNVERIFIED".into();
        }
        let mut s = "system".to_string();
        if t.ca_file.is_some() || t.ca_pem.is_some() {
            s.push_str("+ca");
        }
        if !t.pins.is_empty() {
            s.push_str(&format!("+pinned({})", t.pins.len()));
            if !t.verify_host {
                s.push_str("+no-name-check");
            }
        }
        s
    }

    /// The credential of this profile, preferring the helper's fresh
    /// answer over the stored copy (§3.4). Neither is ever echoed; the
    /// helper's failure aborts the request with its own words.
    pub fn credential(&self) -> Result<Option<Zeroizing<String>>, String> {
        if let Some(cmd) = &self.token_command {
            return run_token_command(cmd).map(Some);
        }
        Ok(self.token.as_ref().filter(|t| !t.trim().is_empty()).map(|t| Zeroizing::new(t.trim().to_string())))
    }
}

#[derive(Debug, Deserialize, Serialize, Clone)]
#[serde(deny_unknown_fields, default)]
pub struct Tls {
    /// Extra root, owner-checked before it joins the store (§2.1).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ca_file: Option<PathBuf>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ca_pem: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub pins: Vec<String>,
    #[serde(default = "yes")]
    pub verify_host: bool,
    #[serde(default)]
    pub insecure: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub i_understand: Option<String>,
}

// Not derived: a profile with no `tls` object at all still means *verify
// the host*; the bool's zero value is the wrong default here, and the
// whole-struct and field defaults both arrive through this path.
impl Default for Tls {
    fn default() -> Self {
        Self { ca_file: None, ca_pem: None, pins: Vec::new(), verify_host: yes(), insecure: false, i_understand: None }
    }
}

/// What the credential *is*, copied from `GET /auth/whoami` after it was
/// checked — display only, never an authorization input (§2.2).
#[derive(Debug, Deserialize, Serialize, Default, Clone)]
#[serde(deny_unknown_fields, default)]
pub struct Identity {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub method: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub user: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token_name: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub logged_in_at: Option<u64>,
}

#[derive(Debug, Deserialize, Serialize, Default, Clone)]
#[serde(deny_unknown_fields, default)]
pub struct LastUsed {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub at: Option<u64>,
    /// The endpoint that answered last; tried first next time (§4.2).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub url: Option<String>,
}

/// The host a URL dials, brackets and port removed — the host
/// `i_understand` must name (§5.4) and the key for credential re-use
/// (§3.3).
pub fn url_host(url: &str) -> String {
    let mut a = url;
    if let Some((_, r)) = a.split_once("://") {
        a = r;
    }
    if let Some((h, _)) = a.split_once('/') {
        a = h;
    }
    if a.starts_with('[') {
        let tail = &a[1.min(a.len())..];
        return tail.split_once(']').map(|(h, _)| h).unwrap_or(tail).to_string();
    }
    a.rsplit_once(':').map(|(h, _)| h).unwrap_or(a).to_string()
}

fn is_loopback_host(h: &str) -> bool {
    h == "localhost" || h == "localhost.local" || h.starts_with("127.") || h == "::1"
}

// ---- reading and writing the file -----------------------------------------

/// The file this invocation reads. `GLIDEX_CONFIG` names it; set to the
/// empty string it means *no file at all*, so CI can declare that a
/// stray profile directory must not change what a pipeline talks to
/// (§2.1).
pub fn file() -> Option<PathBuf> {
    match std::env::var("GLIDEX_CONFIG") {
        Ok(s) => {
            let s = s.trim();
            if s.is_empty() {
                None
            } else {
                Some(PathBuf::from(s))
            }
        }
        Err(_) => dirs::config_dir().map(|d| d.join("glidex").join("config.json")),
    }
}

/// `Ok(None)` = no file (yet): today's behaviour, byte for byte (§3.3).
pub fn load() -> Result<Option<Config>, String> {
    match file() {
        Some(p) => load_from(&p),
        None => Ok(None),
    }
}

/// Reading needs the same discipline as the token file: a bearer token
/// lives here, so group or others reading it, or another owner, refuse
/// the file outright (A3).
pub fn load_from(path: &Path) -> Result<Option<Config>, String> {
    let meta = match std::fs::metadata(path) {
        Ok(m) => m,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(e) => return Err(format!("{}: {}", path.display(), e)),
    };
    if meta.file_type().is_dir() {
        return Err(format!("{}: is a directory", path.display()));
    }
    let mode = meta.permissions().mode() & 0o777;
    if mode & 0o077 != 0 {
        return Err(format!(
            "refusing to read {}: group or others can still read it (mode {:03o}). It holds a bearer token as good as a password; run 'chmod 600 {}' — and if someone could have read it, treat the tokens inside as exposed ('auth logout --revoke')",
            path.display(),
            mode,
            path.display()
        ));
    }
    let euid = nix::unistd::geteuid().as_raw();
    if meta.uid() != euid {
        return Err(format!("refusing to read {}: it is owned by uid {}, not you", path.display(), meta.uid()));
    }
    let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {}", path.display(), e))?;
    // Deny-unknown-fields plus the validation below are the promise that
    // gxctl never edits a file it does not fully understand (§2.2).
    let cfg: Config = serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))?;
    cfg.validate(path)?;
    Ok(Some(cfg))
}

/// Serialize with the same care the reader demanded: never write what we
/// would refuse to read.
pub fn save_to(path: &Path, cfg: &Config) -> Result<(), String> {
    cfg.validate(path)?;
    let dir = path.parent().ok_or("config path has no directory")?;
    std::fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(dir)
        .map_err(|e| format!("{}: {}", dir.display(), e))?;
    std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700)).map_err(|e| format!("{}: {}", dir.display(), e))?;
    let tmp = dir.join(format!(".config.json.{}", std::process::id()));
    let _ = std::fs::remove_file(&tmp);
    let json = serde_json::to_string(cfg).map_err(|e| format!("{}: {e}", path.display()))?;
    let write = || -> io::Result<()> {
        use std::io::Write;
        let mut f = std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&tmp)?;
        f.write_all(json.as_bytes())?;
        f.write_all(b"\n")?;
        f.sync_all()?;
        std::fs::rename(&tmp, path)
    };
    write().map_err(|e| {
        let _ = std::fs::remove_file(&tmp);
        format!("{}: {}", path.display(), e)
    })
}

pub fn save(cfg: &Config) -> Result<(), String> {
    match file() {
        Some(p) => save_to(&p, cfg),
        None => Err("GLIDEX_CONFIG is set empty: there is nowhere to save a profile".into()),
    }
}

/// Merge-write: edit the file's contents (or a fresh v1) and store it,
/// never clobbering the profiles the callback does not touch (§6.1.6).
pub fn edit(cfg: Option<Config>, f: impl FnOnce(&mut Config)) -> Result<(), String> {
    let mut c = cfg.unwrap_or_default();
    f(&mut c);
    save(&c)
}

// ---- choosing a profile ----------------------------------------------------

pub struct Selected<'a> {
    pub name: String,
    pub profile: &'a Profile,
}

/// The name §3's precedence picks; `Ok(None)` means the file has nothing
/// to choose from and the caller keeps today's socket/token ladder.
pub fn chosen(cfg: &Config, want: Option<&str>) -> Result<Option<String>, String> {
    let env = std::env::var("GLIDEX_PROFILE").ok().map(|s| s.trim().to_string()).filter(|s| !s.is_empty());
    let want = want.map(|s| s.trim().to_string()).filter(|s| !s.is_empty());
    let name = want.or(env).or(cfg.current.clone());
    if let Some(name) = name {
        if cfg.profiles.get(&name).is_none() {
            return Err(format!("unknown profile '{}'; this file has: {}", name, cfg.list()));
        }
        return Ok(Some(name));
    }
    if cfg.profiles.is_empty() {
        return Ok(None);
    }
    Err(format!("no current profile; choose one with --profile ({})", cfg.list()))
}

/// The `(name, profile)` pair a login or maintenance command acts on:
/// `name` when given, else the file's `current`. `None` is not an error —
/// commands that can act without operating on a missing profile say so
/// themselves.
pub fn profile_of<'a>(cfg: &'a Option<Config>, name: Option<&str>) -> Option<(&'a String, &'a Profile)> {
    let c = match cfg.as_ref() {
        Some(c) => c,
        None => return None,
    };
    match name {
        Some(n) => c.profiles.iter().find(|(k, _)| k.as_str() == n),
        None => c.current.as_ref().and_then(|cur| c.profiles.iter().find(|(k, _)| *k == cur)),
    }
}

pub fn select<'a>(cfg: &'a Config, want: Option<&str>) -> Result<Option<Selected<'a>>, String> {
    match chosen(cfg, want)? {
        Some(name) => Ok(cfg.profiles.get(&name).map(|profile| Selected { name, profile })),
        None => Ok(None),
    }
}

// ---- the credential helper --------------------------------------------------

/// Run `token_command` (§3.4): its stdout's first line, trimmed, at most
/// 4 KiB; never echoed, never logged, and its failure — with its own
/// words — aborts the request.
pub fn run_token_command(cmd: &str) -> Result<Zeroizing<String>, String> {
    let out = std::process::Command::new("sh").arg("-c").arg(cmd).output().map_err(|e| format!("token_command: {e}"))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr);
        let t: &str = &err;
        let (why, _) = t.split_once('\n').unwrap_or((t, ""));
        let why = why.trim();
        return Err(if why.is_empty() {
            "token_command exited unsuccessfully and said nothing on stderr".into()
        } else {
            format!("token_command: {why}")
        });
    }
    let text = String::from_utf8_lossy(&out.stdout);
    let t: &str = &text;
    let (line, _) = t.split_once('\n').unwrap_or((t, ""));
    let token = Zeroizing::new(line.trim().to_string());
    if token.as_str().is_empty() {
        return Err("token_command printed nothing on stdout".into());
    }
    if token.as_str().len() > 4096 {
        return Err("token_command printed more than 4 KiB; refusing it".into());
    }
    Ok(token)
}

/// The legacy `~/.config/glidex/token`, which `auth login` folds into a
/// profile that ends up dialling the same server (§3.5) and never deletes
/// without `--revoke`.
pub fn legacy_token() -> Result<Option<Zeroizing<String>>, String> {
    match crate::client::token_path() {
        Some(p) => crate::client::read_token_file(&p),
        None => Ok(None),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tls(pins: &[&str], verify_host: bool, insecure: bool, i_understand: Option<&str>) -> Tls {
        Tls { pins: pins.iter().map(|p| p.to_string()).collect(), verify_host, insecure, i_understand: i_understand.map(|s| s.to_string()), ..Default::default() }
    }

    fn full() -> Config {
        let mut cfg = Config::default();
        cfg.current = Some("lab".into());
        cfg.profiles.insert(
            "lab".into(),
            Profile {
                url: vec!["https://lab.example:8841".into(), "https://10.0.0.21:8841".into()],
                cluster_id: Some("6f0c2c9a".into()),
                cluster_name: Some("lab".into()),
                tls: tls(&["sha256/2bf8c6c4f3d2a1b02bf8c6c4f3d2a1b02bf8c6c4f3d2a1b02bf8c6c4f3d2a1b0"], true, false, None),
                token: Some("gxt_secret_value".into()),
                token_command: Some("vault kv get -field=token s/secret".into()),
                identity: Some(Identity { method: Some("pam".into()), user: Some("alice".into()), token_id: Some("3f2a".into()), token_name: Some("gxctl@lab".into()), logged_in_at: Some(1760000000) }),
                added_at: Some(1760000000),
                ..Default::default()
            },
        );
        cfg
    }

    fn write_raw(dir: &tempfile::TempDir, text: &str) -> PathBuf {
        let p = dir.path().join("config.json");
        std::fs::write(&p, text.as_bytes()).unwrap();
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o600)).unwrap();
        p
    }

    #[test]
    fn round_trip_keeps_everything_and_the_modes() {
        let dir = tempfile::TempDir::new().unwrap();
        let p = dir.path().join("conf/config.json");
        save_to(&p, &full()).unwrap();
        assert_eq!(std::fs::metadata(&p).unwrap().permissions().mode() & 0o777, 0o600);
        assert_eq!(std::fs::metadata(p.parent().unwrap()).unwrap().permissions().mode() & 0o777, 0o700);
        let back = load_from(&p).unwrap().unwrap();
        assert_eq!(back.version, CONFIG_VERSION);
        let lab = back.profiles.get("lab").unwrap();
        assert_eq!(lab.url.len(), 2);
        assert_eq!(lab.cluster_id, Some("6f0c2c9a".to_string()));
        assert_eq!(lab.token, Some("gxt_secret_value".to_string()));
        assert_eq!(lab.identity.as_ref().unwrap().token_name, Some("gxctl@lab".to_string()));
        assert_eq!(lab.tls.pins.len(), 1);
        assert!(lab.tls.verify_host, "the default survives the trip");
        // Debug names the profile without ever printing the secret or the
        // helper line (§2.1).
        let shown = format!("{back:?}");
        assert!(!shown.contains("gxt_secret_value") && !shown.contains("vault"), "{shown}");
        let shown = format!("{:?}", full());
        assert!(!shown.contains("gxt_secret_value") && !shown.contains("vault"), "{shown}");
    }

    #[test]
    fn a_world_readable_file_is_refused() {
        let dir = tempfile::TempDir::new().unwrap();
        let p = write_raw(&dir, r#"{"version":1,"profiles":{}}"#);
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o644)).unwrap();
        assert!(load_from(&p).unwrap_err().contains("group or others"), "the token inside is as good as a password");
    }

    #[test]
    fn typos_fail_rather_than_vanish() {
        let dir = tempfile::TempDir::new().unwrap();
        // Unknown field name (§2.2: a hand-editing typo must not silently
        // drop a pin).
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"urlz":["https://x"]}}}"#);
        assert!(load_from(&p).unwrap_err().contains("config.json"), "names the file");
        let p = write_raw(&dir, r#"{"version":2,"profiles":{}}"#);
        assert!(load_from(&p).unwrap_err().contains("version 2"));
        let p = write_raw(&dir, r#"{"version":1,"current":"ghost","profiles":{"lab":{"url":["https://x"]}}}"#);
        assert!(load_from(&p).unwrap_err().contains("ghost"));
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["https://x"],"tls":{"pins":["sha256/zzz"]}}}}"#);
        assert!(load_from(&p).unwrap_err().contains("sha256/zzz"), "the bad pin is quoted back");
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["http://lab.example:8841"]}}}"#);
        assert!(load_from(&p).unwrap_err().contains("https only"));
        // Loopback may be plain.
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["http://localhost:8841"]}}}"#);
        assert!(load_from(&p).unwrap().is_some());
    }

    #[test]
    fn the_waivers_need_what_they_claim() {
        let dir = tempfile::TempDir::new().unwrap();
        // verify_host=false alone would accept any certificate for any host.
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["https://x"],"tls":{"verify_host":false}}}}"#);
        assert!(load_from(&p).unwrap_err().contains("tls.pins"));
        // The bypass is reachable only through its confirmation phrase.
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["https://lab.example:8841"],"tls":{"insecure":true}}}}"#);
        assert!(load_from(&p).unwrap_err().contains("i_understand"));
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["https://lab.example:8841"],"tls":{"insecure":true,"i_understand":"other.example"}}}}"#);
        assert!(load_from(&p).unwrap_err().contains("lab.example"), "the phrase must name this host");
        let p = write_raw(&dir, r#"{"version":1,"profiles":{"lab":{"url":["https://lab.example:8841"],"tls":{"insecure":true,"i_understand":"lab.example"}}}}"#);
        assert!(load_from(&p).unwrap().is_some());
        // Pinned dial-by-IP without a name check is the allowed combo (§2.2).
        let pin = "sha256/".to_string() + &"ab".repeat(32);
        let p = write_raw(&dir, &format!(r#"{{"version":1,"profiles":{{"lab":{{"url":["https://192.168.1.5:8841"],"tls":{{"verify_host":false,"pins":["{pin}"]}}}}}}}}"#));
        assert!(load_from(&p).unwrap().is_some());
    }

    #[test]
    fn choosing_follows_the_precedence() {
        let cfg = full();
        assert_eq!(chosen(&cfg, Some("lab")).unwrap(), Some("lab".to_string()));
        assert!(chosen(&cfg, Some("nope")).unwrap_err().contains("this file has: lab"));
        // No flag: `current`.
        assert_eq!(chosen(&cfg, None).unwrap(), Some("lab".to_string()));
        // Empty file: today's behaviour, not an error (§3.3).
        assert_eq!(chosen(&Config::default(), None).unwrap(), None);
        // Profiles but no current: name them, do not guess (§3.2).
        let mut lonely = Config::default();
        lonely.profiles.insert("prod".into(), Profile { url: vec!["https://p".into()], ..Default::default() });
        assert!(chosen(&lonely, None).unwrap_err().contains("prod"));
        let sel = select(&cfg, Some("lab")).unwrap().unwrap();
        assert_eq!(sel.profile.cluster_name, Some("lab".to_string()));
        assert_eq!(sel.name, "lab");
    }

    #[test]
    fn hosts_come_out_of_urls_whole() {
        assert_eq!(url_host("https://lab.example:8841"), "lab.example");
        assert_eq!(url_host("https://lab.example"), "lab.example");
        assert_eq!(url_host("https://[::1]:8841/x"), "::1");
        assert_eq!(url_host("http://localhost:8841"), "localhost");
        assert!(is_loopback_host("localhost"));
        assert!(is_loopback_host("127.0.0.1"));
        assert!(!is_loopback_host("10.0.0.21"));
    }

    #[test]
    fn the_helper_speaks_one_trimmed_line() {
        let t = run_token_command("printf '  gxt_x \\n  junk\\n'").unwrap();
        assert_eq!(t.as_str(), "gxt_x");
        assert!(run_token_command("exit 3").unwrap_err().contains("exited unsuccessfully"));
        assert!(run_token_command("true").unwrap_err().contains("nothing"));
        let big = format!("printf '{}'", "k".repeat(5000));
        assert!(run_token_command(&big).unwrap_err().contains("4 KiB"));
    }

    #[test]
    fn the_helper_answer_beats_the_stored_copy() {
        // §2.2: `token_command` wins when both are present — a site-wide
        // helper outranks a stale copy, and the precedence is decided per
        // request so fixing the helper fixes gxctl without a re-login.
        let mut p = Profile { url: vec!["https://x".into()], token: Some("gxt_stored".into()), token_command: Some("printf 'gxt_helper\\n'".into()), ..Default::default() };
        assert_eq!(p.credential().unwrap().map(|t| t.as_str().to_string()), Some("gxt_helper".to_string()));
        p.token_command = None;
        assert_eq!(p.credential().unwrap().map(|t| t.as_str().to_string()), Some("gxt_stored".to_string()));
        p.token = Some("   ".into());
        assert!(p.credential().unwrap().is_none(), "whitespace is no credential");
    }

    #[test]
    fn trust_mode_says_what_will_be_checked() {
        assert_eq!(full().profiles.get("lab").unwrap().trust_mode(), "system+pinned(1)");
        let mut p = Profile { url: vec!["https://x".into()], ..Default::default() };
        assert_eq!(p.trust_mode(), "system");
        p.tls.insecure = true;
        assert_eq!(p.trust_mode(), "UNVERIFIED");
        p.tls.insecure = false;
        p.tls.pins = vec!["sha256/".to_string() + &"cd".repeat(32)];
        p.tls.verify_host = false;
        assert_eq!(p.trust_mode(), "system+pinned(1)+no-name-check");
    }
}
